import {
  addDoc,
  collection,
  getDocs,
  limit,
  orderBy,
  query,
  serverTimestamp,
  where,
  updateDoc,
  doc,
} from "firebase/firestore";
import type { SatisfactionResponse } from "../../features/admin/types";
import type { Itinerary } from "../../features/admin/types";

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export type CreateSatisfactionInput = {
  itineraryId?: string;
  surveyToken: string;
  lang: string;
  q1: number;
  q2: number;
  q3: number;
  q4: number;
  q5: number;
  q6: number;
  q7: string;
  q8: string;
  q9: string;
};

export async function getItineraryBySurveyToken(
  token: string
): Promise<(Itinerary & { id: string }) | null> {
  const db = await getDb();
  const q = query(
    collection(db, "itineraries"),
    where("surveyToken", "==", token),
    limit(1)
  );
  const snap = await getDocs(q);
  if (snap.empty) return null;
  const d = snap.docs[0];
  return { id: d.id, ...(d.data() as Itinerary) };
}

export async function generateSurveyToken(itineraryId: string): Promise<string> {
  const db = await getDb();
  const token = crypto.randomUUID();
  await updateDoc(doc(db, "itineraries", itineraryId), {
    surveyToken: token,
  });
  return token;
}

export async function listSatisfactionResponses(): Promise<(SatisfactionResponse & { id: string })[]> {
  const db = await getDb();
  const q = query(collection(db, "satisfactionResponses"), orderBy("submittedAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as SatisfactionResponse) }));
}

export async function createSatisfactionResponse(
  input: CreateSatisfactionInput
): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "satisfactionResponses"), {
    itineraryId: input.itineraryId ?? null,
    surveyToken: input.surveyToken,
    lang: input.lang,
    q1: input.q1,
    q2: input.q2,
    q3: input.q3,
    q4: input.q4,
    q5: input.q5,
    q6: input.q6,
    q7: input.q7,
    q8: input.q8,
    q9: input.q9,
    submittedAt: serverTimestamp(),
  });
  return ref.id;
}
