import React, { useEffect, useState } from "react";
import { graphql } from "gatsby";
import { AdminLayout } from "../../features/admin/components/AdminLayout";
import {
  listSatisfactionResponses,
} from "../../sessionServices/surveys/satisfactionService";
import { getItineraryById } from "../../sessionServices/itineraries/itinerariesService";
import type { SatisfactionResponse } from "../../features/admin/types";
import type { Timestamp } from "firebase/firestore";

type ResponseRow = SatisfactionResponse & {
  id: string;
  itineraryTitle?: string;
};

const STAR_QUESTIONS = ["q1", "q2", "q3", "q4", "q5", "q6"] as const;
const STAR_LABELS: Record<string, string> = {
  q1: "Trip information",
  q2: "Itinerary organization",
  q3: "Accommodation quality",
  q4: "Transportation quality",
  q5: "Price-quality ratio",
  q6: "Overall experience",
};
const TEXT_LABELS: Record<string, string> = {
  q7: "What did you enjoy most?",
  q8: "Customer service comments",
  q9: "Suggestions to improve",
};

function Stars({ value }: { value: number }) {
  return (
    <span className="text-sm">
      {[1, 2, 3, 4, 5].map((s) => (
        <span key={s} className={s <= value ? "text-amber-400" : "text-gray-200"}>
          ★
        </span>
      ))}
    </span>
  );
}

function formatDate(ts: Timestamp | undefined) {
  if (!ts) return "—";
  return ts.toDate().toLocaleDateString("en-CA", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

function average(rows: ResponseRow[], key: keyof Pick<SatisfactionResponse, "q1"|"q2"|"q3"|"q4"|"q5"|"q6">) {
  if (!rows.length) return 0;
  return rows.reduce((s, r) => s + (r[key] ?? 0), 0) / rows.length;
}

export default function SurveysPage() {
  const [rows, setRows] = useState<ResponseRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      const responses = await listSatisfactionResponses();
      const enriched = await Promise.all(
        responses.map(async (r) => {
          if (r.itineraryId) {
            const it = await getItineraryById(r.itineraryId);
            return { ...r, itineraryTitle: it?.title };
          }
          return r;
        })
      );
      setRows(enriched);
      setLoading(false);
    }
    load();
  }, []);

  const generalRows = rows.filter((r) => r.surveyToken === "general");
  const linkedRows = rows.filter((r) => r.surveyToken !== "general");

  return (
    <AdminLayout title="Satisfaction Survey Responses">
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
        </div>
      ) : rows.length === 0 ? (
        <p className="text-sm text-gray-400">No responses yet.</p>
      ) : (
        <div className="space-y-10">
          {/* ── Summary averages ── */}
          <div className="rounded-xl bg-white p-6 shadow-sm ring-1 ring-gray-200">
            <h2 className="mb-4 text-sm font-semibold text-gray-700 uppercase tracking-wide">
              Overall averages ({rows.length} response{rows.length !== 1 ? "s" : ""})
            </h2>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {STAR_QUESTIONS.map((q) => {
                const avg = average(rows, q);
                return (
                  <div key={q} className="rounded-lg bg-gray-50 px-4 py-3">
                    <p className="text-xs text-gray-500">{STAR_LABELS[q]}</p>
                    <div className="mt-1 flex items-center gap-2">
                      <Stars value={Math.round(avg)} />
                      <span className="text-sm font-semibold text-gray-800">
                        {avg.toFixed(1)}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* ── Responses table ── */}
          {[
            { label: "Linked to itinerary", data: linkedRows },
            { label: "General (external clients)", data: generalRows },
          ].map(({ label, data }) =>
            data.length === 0 ? null : (
              <div key={label} className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
                <div className="border-b border-gray-100 bg-gray-50 px-5 py-3">
                  <p className="text-sm font-semibold text-gray-900">{label}</p>
                  <p className="text-xs text-gray-400">{data.length} response{data.length !== 1 ? "s" : ""}</p>
                </div>
                <div className="divide-y divide-gray-50">
                  {data.map((row) => (
                    <div key={row.id}>
                      {/* Row header */}
                      <button
                        className="w-full px-5 py-3 text-left hover:bg-gray-50 transition-colors"
                        onClick={() => setExpanded(expanded === row.id ? null : row.id)}
                      >
                        <div className="flex items-center justify-between gap-4">
                          <div className="min-w-0">
                            <p className="truncate text-sm font-medium text-gray-900">
                              {row.itineraryTitle ?? "External client"}
                            </p>
                            <p className="text-xs text-gray-400">
                              {formatDate(row.submittedAt)} · {row.lang.toUpperCase()}
                            </p>
                          </div>
                          <div className="flex shrink-0 items-center gap-3">
                            <Stars value={row.q6} />
                            <span className="text-xs text-gray-400">
                              {expanded === row.id ? "▲" : "▼"}
                            </span>
                          </div>
                        </div>
                      </button>

                      {/* Expanded detail */}
                      {expanded === row.id && (
                        <div className="border-t border-gray-100 bg-gray-50 px-5 py-4 space-y-4">
                          {/* Star ratings */}
                          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                            {STAR_QUESTIONS.map((q) => (
                              <div key={q} className="flex items-center justify-between rounded-lg bg-white px-3 py-2 ring-1 ring-gray-100">
                                <span className="text-xs text-gray-500">{STAR_LABELS[q]}</span>
                                <Stars value={row[q]} />
                              </div>
                            ))}
                          </div>
                          {/* Open answers */}
                          <div className="space-y-3">
                            {(["q7", "q8", "q9"] as const).map((q) =>
                              row[q] ? (
                                <div key={q}>
                                  <p className="mb-0.5 text-xs font-medium text-gray-500">
                                    {TEXT_LABELS[q]}
                                  </p>
                                  <p className="text-sm text-gray-800 leading-relaxed">
                                    {row[q]}
                                  </p>
                                </div>
                              ) : null
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )
          )}
        </div>
      )}
    </AdminLayout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
